/* ---------- INTEGRATIONS: pinned cards slide in right→left and stack on top ---------- */
(function () {
  var sec = document.querySelector('[data-intstack]'); if (!sec) return;
  var cards = Array.prototype.slice.call(sec.querySelectorAll('.intcard'));
  if (!cards.length) return;
  var head = sec.querySelector('.intstack__head');
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function isMobile() { return window.matchMedia('(max-width: 860px)').matches; }
  var N = cards.length, SEG = 560, HOLD = 40, MAXD = 4, LEAD = 0.9, ENTER = 0.9;
  function clamp(v) { return Math.max(0, Math.min(1, v)); }
  function ease(t) { return 1 - Math.pow(1 - t, 3); }   /* easeOutCubic */
  function reset() { sec.style.height = ''; if (head) head.style.transform = ''; cards.forEach(function (c) { c.style.transform = ''; c.style.zIndex = ''; }); }
  function layout() {
    if (isMobile() || reduce) { reset(); return; }
    sec.style.height = (window.innerHeight + (N - 1 + LEAD) * SEG + HOLD) + 'px';
    update();
  }
  function update() {
    if (isMobile() || reduce) return;
    var raw = (-sec.getBoundingClientRect().top) / SEG;   /* segments scrolled since pin */
    var prog = raw - LEAD;
    for (var i = 0; i < N; i++) {
      var rel = prog - i, x = 0, sc = 1;
      if (rel <= -1) {                       /* waiting off to the right */
        x = 118;
      } else if (rel < -1 + ENTER) {         /* sliding straight in from the right */
        x = 118 * (1 - ease((rel + 1) / ENTER));
      } else if (rel < 0) {                  /* landed — dwell at its place so it can be read */
        x = 0;
      } else {                               /* the next card arrives — drift left to peek */
        var d = Math.min(rel, MAXD);
        x = -d * 2.0; sc = 1 - d * 0.02;
      }
      cards[i].style.zIndex = i + 1;
      cards[i].style.transform = 'translate3d(' + x.toFixed(2) + '%,0,0) scale(' + sc.toFixed(3) + ')';
    }
    /* title eases up into its (higher) resting spot at the same time as the first card slides in */
    if (head) {
      var tp = ease(clamp(raw / 0.9));
      head.style.transform = 'translateY(' + (52 * (1 - tp)).toFixed(1) + 'px)';
    }
  }
  var ticking = false;
  window.addEventListener('scroll', function () { if (!ticking) { ticking = true; requestAnimationFrame(function () { update(); ticking = false; }); } }, { passive: true });
  window.addEventListener('resize', layout);
  window.addEventListener('load', layout);
  if (document.fonts && document.fonts.ready) { document.fonts.ready.then(layout); }
  layout();
})();

/* CONTACT form → sales endpoint */
(function () {
  var form = document.getElementById('contactForm'); if (!form) return;
  var btn = document.getElementById('contactSubmit');
  var status = document.getElementById('contactStatus');
  var ENDPOINT = 'https://api-webstrail.webstrail.com/api/v1/contact-us/send-sales-mail';
  function say(msg, ok) {
    status.hidden = false;
    status.textContent = msg;
    status.classList.toggle('is-ok', !!ok);
    status.classList.toggle('is-err', !ok);
  }
  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var name = form.querySelector('#f-name').value.trim();
    var company = form.querySelector('#f-co').value.trim();
    var email = form.querySelector('#f-email').value.trim();
    var description = form.querySelector('#f-msg').value.trim();
    if (!name || !email) { say('Please add your name and work email.', false); return; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { say('Please enter a valid email address.', false); return; }
    var original = btn.textContent;
    btn.disabled = true; btn.textContent = 'Sending…';
    fetch(ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: name, company: company, email: email, description: description })
    }).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      form.reset();
      say('Thanks — we’ll be in touch within one business day to book your call.', true);
    }).catch(function () {
      say('Something went wrong. Please email sales@webstrail.com and we’ll set up your call.', false);
    }).finally(function () {
      btn.disabled = false; btn.textContent = original;
    });
  });
})();
